const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body || {};
  const entries = body.entry || [];

  if (body.object !== 'instagram') {
    results.push({
      json: {
        ignored: true,
        reason: 'Not an Instagram event'
      }
    });
    continue;
  }

  for (const entry of entries) {
    const businessId = entry.id;
    const events = entry.messaging || [];

    for (const event of events) {
      const senderId = event.sender?.id;
      const recipientId = event.recipient?.id;
      const messageId = event.message?.mid;
      const timestamp = event.timestamp;

      if (!event.message) {
        results.push({
          json: {
            ignored: true,
            reason: 'Non-message event'
          }
        });
        continue;
      }

      if (senderId === businessId) {
        results.push({
          json: {
            ignored: true,
            reason: 'Business account own message'
          }
        });
        continue;
      }

      const missingFields = [];

      if (!senderId) missingFields.push('sender_id');
      if (!recipientId) missingFields.push('recipient_id');
      if (!messageId) missingFields.push('message_id');
      if (!timestamp) missingFields.push('timestamp');

      if (missingFields.length > 0) {
        results.push({
          json: {
            ignored: false,
            is_valid: false,
            reason: 'Missing required fields',
            missing_fields: missingFields
          }
        });
        continue;
      }

      const text = event.message.text || '';
      const hasAttachments = Array.isArray(event.message.attachments)
        && event.message.attachments.length > 0;

      // Ignore unsupported attachments and empty messages.
      if (!text.trim()) {
        results.push({
          json: {
            ignored: true,
            is_valid: false,
            sender_id: senderId,
            message_id: messageId,
            reason: hasAttachments
              ? 'Unsupported attachment'
              : 'Empty message',
            message_type: hasAttachments ? 'attachment' : 'unsupported'
          }
        });
        continue;
      }

      results.push({
        json: {
          ignored: false,
          is_valid: true,
          sender_id: senderId,
          recipient_id: recipientId,
          business_account_id: businessId,
          message_id: messageId,
          timestamp: timestamp,
          message_text: text,
          message_type: 'text',
          unsupported_attachment: false
        }
      });
    }
  }
}

return results;

const input = $input.item.json;

// Find the AI response text
const possibleResponses = [
  input.content?.parts?.map(p => p.text || '').join(''),
  input.candidates?.[0]?.content?.parts?.map(p => p.text || '').join(''),
  input.text,
  input.output,
  input.response,
  input.message?.content
];

let rawText = possibleResponses.find(
  value => typeof value === 'string' && value.trim()
);

let result;

try {
  if (input.reply_message && input.customer_intent) {
    result = input;
  } else {
    if (!rawText) {
      throw new Error('No AI response found');
    }

    rawText = rawText
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .trim();

    const start = rawText.indexOf('{');
    const end = rawText.lastIndexOf('}');

    if (start === -1 || end === -1) {
      throw new Error('Invalid JSON response');
    }

    result = JSON.parse(rawText.slice(start, end + 1));
  }

  const allowedIntents = [
    'General Inquiry',
    'SWC Information Inquiry',
    'Pricing Inquiry',
    'Interested Prospect',
    'Enrollment Inquiry',
    'Needs Human Assistance'
  ];

  const allowedInterest = ['Low', 'Medium', 'High'];

  if (
    !result.reply_message ||
    !allowedIntents.includes(result.customer_intent) ||
    !allowedInterest.includes(result.interest_level) ||
    typeof result.handoff_required !== 'boolean'
  ) {
    throw new Error('Incomplete AI response');
  }

  return {
    json: {
      ...result,
      ai_output_valid: true,
      handoff_reason: result.handoff_reason || ''
    }
  };

} catch (error) {
  return {
    json: {
      reply_message: '',
      customer_intent: 'Needs Human Assistance',
      interest_level: 'Low',
      handoff_required: true,
      handoff_reason: 'AI response could not be validated: ' + error.message,
      ai_output_valid: false
    }
  };
}

const data = $input.item.json;
const incoming = $('Validate Incoming Message').item.json;

return {
  json: {
    ...data,
    sender_id: incoming.sender_id,
    message_id: incoming.message_id,
    recipient_id: incoming.recipient_id,
    business_account_id: incoming.business_account_id,

    handoff_status: 'Assigned',
    handoff_required: true,

    handoff_summary: data.reply_message || 'Customer requires human assistance.',

    handoff_notification: {
      customer_id: incoming.sender_id,
      reason: data.handoff_reason || 'Human assistance requested',
      customer_intent: data.customer_intent || 'Needs Human Assistance',
      status: 'Assigned'
    },

    ai_reply_stopped: true
  }
};

const ai = $input.item.json;
const incoming = $('Validate Incoming Message').item.json;

const customerId = incoming.sender_id;
const reply = ai.reply_message;

if (!customerId || !reply) {
  throw new Error('Missing customer ID or AI reply');
}

return {
  json: {
    sender_id: customerId,
    recipient_id: incoming.recipient_id,
    business_account_id: incoming.business_account_id,
    message_id: incoming.message_id,

    reply_message: reply,
    customer_intent: ai.customer_intent,
    interest_level: ai.interest_level,

    instagram_request_body: {
      recipient: {
        id: customerId
      },
      message: {
        text: reply
      }
    },

    reply_status: 'Prepared',
    send_enabled: false
  }
};

const data = $input.item.json;

const statusCode = data.statusCode || data.status || null;
const apiResponse = data.body || data;

const isMock = data.mock_response === true || data.send_enabled === false;

let apiStatus = 'Unknown';
let errorMessage = '';

if (isMock && statusCode >= 200 && statusCode < 300) {
  apiStatus = 'Mock Success';
} else if (isMock && statusCode !== null) {
  apiStatus = 'Failed';
  errorMessage = apiResponse.message || 'Mock Instagram API failure';
} else if (statusCode >= 200 && statusCode < 300) {
  apiStatus = 'Accepted';
} else if (statusCode !== null) {
  apiStatus = 'Failed';
  errorMessage = apiResponse.message || 'Instagram API request failed';
}

return {
  json: {
    ...data,
    api_status: apiStatus,
    api_response: apiResponse,
    api_error: errorMessage,
    message_sent: !isMock && apiStatus === 'Accepted'
  }
};

const items = $input.all();

// Change to 'success' or 'failure' when testing.
const MOCK_OUTCOME = 'success';

return items.map(item => {
  const data = item.json;

  if (MOCK_OUTCOME === 'success') {
    return {
      json: {
        ...data,
        mock_response: true,
        statusCode: 200,
        body: {
          success: true,
          message: 'Mock Instagram API success',
          recipient_id: data.sender_id
        }
      }
    };
  }

  return {
    json: {
      ...data,
      mock_response: true,
      statusCode: 500,
      body: {
        success: false,
        message: 'Mock Instagram API failure'
      }
    }
  };
});
